"""Shipping costs and parcel splitting. See docs/shipping.md."""

from shoplib.errors import ShopError

# (upper bound in grams, cost in cents)
TIERS = [(1000, 500), (2000, 800), (5000, 1200), (20000, 2500)]


def shipping_cost(weight_g: int) -> int:
    """Cost in cents of one parcel of `weight_g` grams. See docs/shipping.md."""
    if weight_g <= 0:
        raise ValueError("weight must be positive")
    for limit, cost in TIERS:
        if weight_g < limit:
            return cost
    raise ValueError("parcel is too heavy")


def split_parcels(items: list[tuple[str, int, int]], max_weight_g: int) -> list[list[str]]:
    """Split order items into parcels. See docs/shipping.md."""
    return [[sku for sku, _ in parcel] for parcel in _pack_parcels(items, max_weight_g)]


def shipment_cost(items: list[tuple[str, int, int]], max_weight_g: int) -> int:
    """Total shipping cost of an order. See docs/shipping.md."""
    parcels = _pack_parcels(items, max_weight_g)
    return sum(shipping_cost(sum(weight for _, weight in parcel)) for parcel in parcels)


def _pack_parcels(items: list[tuple[str, int, int]], max_weight_g: int) -> list[list[tuple[str, int]]]:
    """Return parcels of (SKU, unit weight), retaining weights for pricing."""
    if not isinstance(max_weight_g, int) or isinstance(max_weight_g, bool) or max_weight_g < 1:
        raise ShopError("maximum parcel weight must be positive")
    if not isinstance(items, list):
        raise ShopError("items must be a list")

    units: list[tuple[str, int]] = []
    for item in items:
        if not isinstance(item, (tuple, list)) or len(item) != 3:
            raise ShopError("each item must contain a SKU, weight, and quantity")
        sku, unit_weight_g, qty = item
        if not isinstance(sku, str):
            raise ShopError("SKU must be a string")
        if not isinstance(unit_weight_g, int) or isinstance(unit_weight_g, bool) or unit_weight_g < 1:
            raise ShopError("unit weight must be positive")
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            raise ShopError("quantity must be positive")
        if unit_weight_g > max_weight_g:
            raise ShopError("unit is heavier than the maximum parcel weight")
        units.extend([(sku, unit_weight_g)] * qty)

    units.sort(key=lambda unit: (-unit[1], unit[0]))
    parcels: list[list[tuple[str, int]]] = []
    parcel_weights: list[int] = []
    for unit in units:
        for index, parcel_weight in enumerate(parcel_weights):
            if parcel_weight + unit[1] <= max_weight_g:
                parcels[index].append(unit)
                parcel_weights[index] += unit[1]
                break
        else:
            parcels.append([unit])
            parcel_weights.append(unit[1])
    return parcels
import pytest

from shoplib.errors import ShopError
from shoplib.shipping import shipment_cost, shipping_cost, split_parcels


def test_tiers():
    assert shipping_cost(300) == 500
    assert shipping_cost(1500) == 800
    assert shipping_cost(4000) == 1200
    assert shipping_cost(12000) == 2500


def test_invalid_weight():
    with pytest.raises(ValueError):
        shipping_cost(0)
    with pytest.raises(ValueError):
        shipping_cost(25000)


def test_split_parcels_uses_heaviest_first_sku_ties_and_first_fit():
    items = [("Z", 4, 1), ("E", 6, 1), ("A", 4, 1), ("D", 6, 1)]

    assert split_parcels(items, 10) == [["D", "A"], ["E", "Z"]]


def test_split_parcels_expands_quantities_and_allows_exact_capacity():
    assert split_parcels([("B", 6, 1), ("A", 4, 2)], 10) == [["B", "A"], ["A"]]


def test_split_parcels_empty_items():
    assert split_parcels([], 1000) == []


@pytest.mark.parametrize(
    "items,max_weight_g",
    [
        ([("A", 11, 1)], 10),
        ([("A", 1, 0)], 10),
        ([("A", 0, 1)], 10),
        ([("A", 1, 1)], 0),
    ],
)
def test_split_parcels_rejects_invalid_weights_and_quantities(items, max_weight_g):
    with pytest.raises(ShopError):
        split_parcels(items, max_weight_g)


def test_shipment_cost_prices_the_packed_parcels():
    items = [("A", 4000, 1), ("A", 3000, 1), ("A", 800, 1)]

    assert shipment_cost(items, 5000) == shipping_cost(4800) + shipping_cost(3000)
